    void rec::pop(visitor* v, ast::Node node)
    {
        auto top = len(v->stack) - 1;
        auto current = v->stack[top];

        auto push = & v->events[current.index];
        auto parent = & v->stack[top - 1];

        // make push event refer to pop
        push->index = int32_t(len(v->events));
        // accumulate type bits into parent
        parent->typAccum |= current.typAccum | push->typ;

        v->stack = v->stack.make_slice(0, top);

        v->events = append(v->events, gocpp::Init<event>([=](auto& x) {
            x.node = node;
            x.typ = current.typAccum;
            x.index = current.index;
            x.parent = current.edgeKindAndIndex;
        }));
    }

